import{_ as t,l as i,o as e,c as n,v as l,p as s,x as r,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"劳动–闲暇","description":"","frontmatter":{"title":"劳动–闲暇","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/labor-leisure.md","filePath":"econ/labor-leisure.md","lastUpdated":1789023840000}'),m={name:"econ/labor-leisure.md"};function E(h,a,_,u,B,A){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="劳动–闲暇" tabindex="-1">劳动–闲暇 <a class="header-anchor" href="#劳动–闲暇" aria-label="Permalink to &quot;劳动–闲暇&quot;">​</a></h1><div class="epigraph"><p>把闲暇当成一种商品，工资就是它的价格。劳动供给是时间禀赋减去闲暇需求。</p><footer>—— 据 Varian, Microeconomic Analysis 中劳动供给的处理整理</footer></div><p><a href="/econ/gorman-polar">上一课</a>（Gorman 加总）。把确定消费上的闭环收束：从 \\(x\\) 可以走回 \\(u\\)，GARP 与 \\(S\\) 对称是两条路。本课不重写 Afriat，也不再积斯勒茨基矩阵。缺口是：同一套消费者理论还没把时间算进去。把闲暇当商品，工资是闲暇的价格，劳动供给才是马歇尔需求的一支，而不是另起的「工作经济学」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>确定消费的 \\(x\\in\\mathbb{R}_+^n\\) 没有小时。人却在劳动与闲暇之间选：时间禀赋 \\(T\\)，闲暇 \\(\\ell\\)，劳动 \\(n=T-\\ell\\)，消费 \\(c\\) 由工资 \\(w\\) 与非劳动收入 \\(m\\) 支付。若仍把劳动当原始「坏东西」另写一套公理，与上一课恢复出来的偏好接不上。缺口是改商品空间，不改理性。</p><p>取两商品 \\((c,\\ell)\\)，预算</p> \\[c+w\\ell=wT+m. \\]<p>右端是全收入：把全部时间按工资折成钱，再加非劳动收入。闲暇的价格是 \\(w\\)，消费的价格归一。马歇尔闲暇需求 \\(\\ell(w,m)\\)；劳动供给 \\(n(w,m)=T-\\ell(w,m)\\)。局部非饱和仍迫使花光全收入。可积性上一课已经保证：若这套需求来自偏好，斯勒茨基在 \\((c,\\ell)\\) 上对称、负半定。</p><h3 id="工资涨有两件事-与吉芬同一分解" tabindex="-1">工资涨有两件事，与吉芬同一分解 <a class="header-anchor" href="#工资涨有两件事-与吉芬同一分解" aria-label="Permalink to &quot;工资涨有两件事，与吉芬同一分解&quot;">​</a></h3><p>\\(w\\) 升，闲暇相对变贵（替代：少歇、多干），全收入也升（收入：若闲暇正常，多歇、少干）。劳动供给的工资弹性没有先验符号。向后弯的供给曲线是收入效应压过替代效应，不是悖论。</p><p><span class="marginnote">非劳动收入 \\(m\\) 才是闲暇的「财富」。工资同时出现在价格与全收入里，比较静态必须拆开，不能只看 \\(dn/dw\\) 的毛号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把上一课的装置原样搬来。间接效用 \\(v(w,m)\\)（价格向量 \\((1,w)\\)，财富 \\(wT+m\\)）。Roy 读出 \\(\\ell\\) 与 \\(c\\)。希克斯闲暇钉住效用，替代效应 \\(\\partial h_\\ell/\\partial w\\le 0\\)。劳动的替代效应因此非负：补偿过的劳动供给向上。毛效应 \\(dn/dw\\) 仍可负——闲暇劣等极少见，向后弯通常来自闲暇正常且收入项够大。</p><p>角点：\\(n=0\\) 是闲暇 \\(\\ell=T\\)，保留工资高于意愿才进市场。Kuhn–Tucker 与<a href="/econ/interior-corner">内点与角点</a>同一套：不参与劳动当互补松弛，不是另定义「失业」。本课不把宏观失业理论塞进来。</p>',14)),(e(),s(d,null,{default:r(()=>[c(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%97%B6%E9%97%B4%E7%A6%80%E8%B5%8B%20T%22%5D%20--%3E%20B%5B%22%E5%85%A8%E6%94%B6%E5%85%A5%E9%A2%84%E7%AE%97%20c%20%2B%20w%E2%84%93%20%3D%20wT%20%2B%20m%22%5D%0A%20%20B%20--%3E%20LEI%5B%22%E9%97%B2%E6%9A%87%E9%9C%80%E6%B1%82%20%E2%84%93(w%2Cm)%22%5D%0A%20%20LEI%20--%3E%20N%5B%22%E5%8A%B3%E5%8A%A8%E4%BE%9B%E7%BB%99%20n%20%3D%20T%20-%20%E2%84%93%22%5D%0A%20%20N%20--%3E%20BACK%5B%22%E6%94%B6%E5%85%A5%E6%95%88%E5%BA%94%E5%A4%A7%EF%BC%9A%E4%BE%9B%E7%BB%99%E5%90%91%E5%90%8E%E5%BC%AF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>显示偏好同样适用：观测 \\((w^t,m^t,c^t,\\ell^t)\\) 可以跑 GARP。失败可能是跨期、家庭加总，不一定是「人不理性」——上一课边界已经警告对象切错。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>劳动供给是闲暇需求的镜像。需求定律管闲暇的补偿项；劳动的「向上倾斜」只在替代压过收入时成立。这与吉芬对称：那里劣等品的马歇尔需求可以向上，这里正常闲暇的马歇尔劳动供给可以向下。两边都是斯勒茨基收入项在翻号，不是偏好坏了。</p><p>课税、转移支付改的是 \\(w\\) 与 \\(m\\) 的组合。工资税压低净工资，替代鼓励歇着；若同时用一次总付补回全收入，只剩替代，劳动供给上升。这就是为什么补偿劳动供给弹性进入最优税收，而不是毛弹性。本课只开这个口，不写公共财政。</p><p><span class="marginnote">家庭生产、家务、第二种工资，把 \\(\\ell\\) 再切开。本课停在一种闲暇、一种市场劳动，对象仍是两商品消费者。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>时间不可分、加班约束、制度工时，都会把 \\(\\ell\\) 变成离散或有上限。向后弯在个体层可能出现，市场加总后常被参与率的扩展边际盖住。本栏主干仍用连续 \\((c,\\ell)\\)，因为要接上已有的 \\(x(p,w)\\)。</p><p>也不要把本课读成宏观劳动市场出清。这里没有企业劳动需求、没有失业存量；工资是参数，与马歇尔需求里的 \\(p\\) 同一地位。风险、跨期储蓄若塞进同一个静态 \\((c,\\ell)\\)，可积失败只说明对象切错。下一课序的彩票与欧拉方程另起。</p><p>后课默认：劳动供给是闲暇的马歇尔需求镜像；工资是闲暇价格；向后弯是收入效应，不是新公理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>闲暇是商品，工资是它的价格；劳动是 \\(T-\\ell\\)。</li><li>预算用全收入写；瓦尔拉斯定律仍是花光。</li><li>补偿劳动供给向上；毛供给可向后弯。</li><li>参与是闲暇角点，同一套 Kuhn–Tucker。</li><li>出处：Varian, <em>Microeconomic Analysis</em> 的劳动供给章节。</li></ul>',11))])}const w=t(m,[["render",E]]);export{f as __pageData,w as default};
